const crypto = require('crypto');

return $input.all().map(item => {
  const phone = item.json.wa_phone;

  const phone_hash = crypto
    .createHmac('sha256', $env.PHONE_PEPPER)
    .update(phone)
    .digest('hex');

  return {
    json: {
      ...item.json,
      phone_hash,
      phone_masked: phone.slice(0, 5) + '****' + phone.slice(-3)
    }
  };
});

const cfg = $input.first().json;
const p = new Intl.DateTimeFormat('en-GB', { timeZone:'Africa/Lagos', weekday:'short',
  hour:'2-digit', hour12:false }).formatToParts(new Date());
const get = t => p.find(x => x.type === t).value;
const hour = Number(get('hour')) % 24;
const open = cfg.hours.days.includes(get('weekday')) && hour >= cfg.hours.open && hour < cfg.hours.close;
return { json: { ...cfg, after_hours: !open } };

const cfg   = $('Business Hours').first().json;
const base  = $('Hash and Mask Phone Number').first().json;      // message context plus after_hours
const state = $('Load State').first().json || {};    // empty item when no active state
const hasState = !!state.phone_hash;

// lowercase, strip punctuation, collapse spaces
const t = (base.text || '').toLowerCase()
  .replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();

// whole-word phrase match without regex
const has = list => list.find(p => (' ' + t + ' ').includes(' ' + p + ' '));

// cancel must be the whole message (or start with 'cancel'), so an address
// like 'Bus stop, Ikeja' does not cancel the order
const cancelHit = cfg.interrupts.cancel.find(p => t === p || (p === 'cancel' && t.startsWith('cancel ')));

let override = null, reason = null;
const h = has(cfg.interrupts.human_request);
const c = has(cfg.interrupts.complaint);

if (h)              { override = 'human_request'; reason = 'keyword:' + h; }
else if (c)         { override = 'complaint';     reason = 'keyword:' + c; }
else if (cancelHit) {
  if (hasState)     { override = 'cancel';        reason = 'user_cancelled_flow'; }
  else              { override = 'human_request'; reason = 'cancel_without_active_flow'; }
}

return [{ json: {
  ...base,
  override, override_reason: reason,
  has_state: hasState,
  state_step: hasState ? state.step : null,
  state_intent: hasState ? state.intent : null
} }];

const cfg = $('Extract Data from SW-Config').first().json;
const text = $('Hash and Mask Phone Number').first().json.text.toLowerCase();
if (/\bzh-\d+/i.test(text)) return { json: { ...$input.first().json, intent:'order_status', confidence:1, runner_up:null } };

const has = kw => new RegExp(`\\b${kw}\\b`).test(text);
const scored = Object.entries(cfg.intents).map(([intent, kws]) => ({
  intent, score: Object.entries(kws).filter(([k]) => has(k)).reduce((s,[,w]) => s + w, 0)
})).sort((a, b) => b.score - a.score);

const [top, second] = scored;
let intent = 'unknown', confidence = 0;
if (top.score > 0) {
  intent = top.intent;
  const margin = (top.score - second.score) / top.score;
  confidence = +(Math.min(top.score, 1) * (0.5 + 0.5 * margin)).toFixed(2);
}
return { json: { ...$input.first().json, intent, confidence, runner_up: second.score > 0 ? second.intent : null } };

const item =$input.first().json;

const raw  = (item.text || '').toLowerCase();

// 1. Keep only letters, digits, spaces and hyphens, then collapse spaces
let text = raw.replace(/[^\p{L}\p{N}\s-]/gu, ' ').replace(/\s+/g, ' ').trim();

// 2. Remove whole phrases first, longest first
const phrases = [
  'how much is', 'how much are', 'how much does', 'how much for', 'how much',
  'what is the price of', 'what is the price for', 'price of', 'price for',
  'cost of', 'do you have', 'do you sell', 'is there', 'are there',
  'i want to know', 'i would like to know', 'can i get', 'can i buy',
  'is available', 'are available', 'in stock', 'please', 'pls'
];
for (const p of phrases) {
  text = text.replace(new RegExp(`\\b${p}\\b`, 'g'), ' ');
}

// 3. Stopwords, removed as whole words only
const stopwords = new Set([
  'the', 'a', 'an', 'is', 'are', 'for', 'of', 'to', 'me', 'my', 'i', 'you', 'your',
  'any', 'some', 'this', 'that', 'it', 'and', 'or', 'what', 'whats', 'how', 'much',
  'price', 'cost', 'available', 'stock', 'have', 'got', 'hi', 'hello'
]);

// 4. Tokenise, drop stopwords and 1-letter leftovers, singularise, dedupe, cap at 6
const tokens = [...new Set(
  text.split(' ')
    .filter(t => t.length >= 2 && !stopwords.has(t))
    .map(t => (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) ? t.slice(0, -1) : t)
)].slice(0, 6);

// 5. Nothing left means no product was named (for example just "price?")
if (tokens.length === 0) {
  return [{ json: { ...item, needs_clarification: true, search_tokens: [], sql: null } }];
}

const where = tokens
  .map(t => `(name ILIKE '%${t}%' OR COALESCE(keywords,'') ILIKE '%${t}%')`)
  .join(' AND ');
const sql = `SELECT sku, name, price_ngn, stock FROM products WHERE ${where} ORDER BY LENGTH(name) LIMIT 3`;

return [{ json: { ...item, needs_clarification: false, search_tokens: tokens, sql } }];

const ctx  = $('Extract Search Texts').first().json;

const rows = $input.all().map(i => i.json).filter(r => r.name);
const naira = n => '₦' + Number(n).toLocaleString('en-NG');

let reply;
if (rows.length === 0) {
  reply = 'I could not find that item. Check the name, or send CATALOGUE to see everything we have in stock.';
} else if (rows.length === 1) {
  const r = rows[0];
  reply = r.stock > 0
    ? `The ${r.name} costs ${naira(r.price_ngn)}. We currently have ${r.stock} in stock.`
    : `The ${r.name} costs ${naira(r.price_ngn)}, but it is currently out of stock.`;
} else {
  reply = 'I found a few matches:\n'
    + rows.map((r, i) => `${i + 1}. ${r.name} - ${naira(r.price_ngn)}${r.stock > 0 ? '' : ' (out of stock)'}`).join('\n')
    + '\n\nPlease send the full name of the one you want.';
}

return [{ json: { ...ctx, reply_text: reply } }];

const item = $input.first().json;               // message context from Switch Intent or Route by State
const text = (item.text || '').toUpperCase();

const found = text.match(/\bZH-\d+\b/);         // anything shaped like an order ID
let order_id = null, lookup_status;

if (!found) lookup_status = 'missing_id';
else if (!/^ZH-\d{5}$/.test(found[0])) lookup_status = 'bad_format';   // for example ZH-12
else { order_id = found[0]; lookup_status = 'valid'; }

// Safe to inline: order_id passed the strict format check and phone_hash is the hex HMAC output.
// When there is no valid ID the query matches nothing, so the node below still runs.
const sql = order_id
  ? `SELECT order_id, status, updated_at FROM orders WHERE order_id='${order_id}' AND phone_hash='${item.phone_hash}'`
  : `SELECT order_id, status, updated_at FROM orders WHERE false`;

return [{ json: { ...item, order_id, lookup_status, sql } }];

