const base = $input.first().json;
const m = (base.text || '').toUpperCase().match(/\bZH-\d{5}\b/);

const context = {
  order_id: m ? m[0] : null,
  text: (base.text || '').slice(0, 300)
};

return [{ json: { ...base, context: JSON.stringify(context) } }];

const item = $input.first().json;

const raw  = (item.text || '').toLowerCase();

// 1. Keep only letters, digits, spaces and hyphens, then collapse spaces
let text = raw.replace(/[^\p{L}\p{N}\s-]/gu, ' ').replace(/\s+/g, ' ').trim();

