  'how much is', 'how much are', 'how much does', 'how much for', 'how much',
  'what is the price of', 'what is the price for', 'price of', 'price for',
  'cost of', 'do you have', 'do you sell', 'is there', 'are there',
  'i want to know', 'i would like to know', 'can i get', 'can i buy',
  'is available', 'are available', 'in stock', 'please', 'pls'
];
for (const p of phrases) {
  text = text.replace(new RegExp(`\\b${p}\\b`, 'g'), ' ');
}

// 3. Stopwords, removed as whole words only
const stopwords = new Set([
  'the', 'a', 'an', 'is', 'are', 'for', 'of', 'to', 'me', 'my', 'i', 'you', 'your',
  'any', 'some', 'this', 'that', 'it', 'and', 'or', 'what', 'whats', 'how', 'much',
  'price', 'cost', 'available', 'stock', 'have', 'got', 'hi', 'hello'
]);

// 4. Tokenise, drop stopwords and 1-letter leftovers, singularise, dedupe, cap at 6
const tokens = [...new Set(
  text.split(' ')
    .filter(t => t.length >= 2 && !stopwords.has(t))
    .map(t => (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) ? t.slice(0, -1) : t)
)].slice(0, 6);

// 5. Nothing left means no product was named (for example just "price?")
if (tokens.length === 0) {
  return [{ json: { ...item, needs_clarification: true, search_tokens: [], sql: null } }];
}

const where = tokens
  .map(t => `(name ILIKE '%${t}%' OR COALESCE(keywords,'') ILIKE '%${t}%')`)
  .join(' AND ');
const sql = `SELECT sku, name, price_ngn, stock FROM products WHERE ${where} ORDER BY LENGTH(name) LIMIT 3`;

return [{ json: { ...item, needs_clarification: false, search_tokens: tokens, sql } }];

const msg = $input.first().json.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!msg) return { json: { valid: false, ignore: true } };   // delivery and read receipts

const type = msg.type;
const text = type === 'text' ? msg.text?.body
  : type === 'button' ? msg.button?.text
  : type === 'interactive' ? (msg.interactive?.button_reply?.title ?? msg.interactive?.list_reply?.title)
  : '';
const errors = [];
if (!msg.id) errors.push('missing_message_id');
if (!/^\d{10,15}$/.test(msg.from || '')) errors.push('bad_phone');
if (type === 'text' && !(text || '').trim()) errors.push('empty_text');

return { json: {
  valid: errors.length === 0, errors,
  request_id: msg.id, wa_message_id: msg.id, wa_phone: msg.from, msg_type: type,
  is_text: ['text','button','interactive'].includes(type),
  text: (text || '').trim().slice(0, 1000),
  image: msg.image?.id
}};

const cfg  = $('Extract Data from SW-Config').first().json;
const st   = $('Load State').first().json;
const text = $('Normalize').first().json.text;
const rows = $('List Products').all().length ? $('List Products').all().map(i => i.json).filter(r => r.sku) : [];
const c = JSON.parse(st.collected_json || '{}');
let step = st.step, attempts = st.attempts || 0, reply = '', advance = false, done = false;
const naira = n => '₦' + Number(n).toLocaleString('en-NG');

if (step === 'item') {
  if (rows.length === 1 && rows[0].stock > 0) {
    c.item = rows[0]; step = 'qty'; advance = true;
    reply = `${rows[0].name} is ${naira(rows[0].price_ngn)}. How many would you like?`;
  } else if (rows.length === 1) reply = `Sorry, ${rows[0].name} is out of stock. Want something else?`;
  else if (rows.length > 1) reply = 'I found:\n' + rows.map((r,i) => `${i+1}. ${r.name}`).join('\n') + '\nPlease send the full name.';
  else reply = 'I could not find that item. Please send the product name.';
}
else if (step === 'qty') {
  const q = parseInt((text.match(/\d+/) || [])[0], 10), max = Math.min(cfg.max_qty, c.item.stock);
  if (q >= 1 && q <= max) { c.qty = q; step = 'address'; advance = true;
    reply = 'Please send your full delivery address (we deliver to Lagos, Abuja and Port Harcourt).'; }
  else reply = `Please send a number between 1 and ${max}.`;
}
else if (step === 'address') {
  const t = text.toLowerCase();
  const zone = cfg.zones.find(z => z.match.some(m => new RegExp(`\\b${m}\\b`).test(t)));
  if (text.length >= 10 && zone) { c.address = text; c.zone = zone.label; c.fee = zone.fee;
    step = 'name'; advance = true; reply = 'Thanks. What name should we put on the order?'; }
  else reply = 'I need a full address in Lagos, Abuja or Port Harcourt (street, area, city). Please resend it.';
}
else if (step === 'name') {
  if (/^[\p{L}][\p{L} .'-]{1,59}$/u.test(text)) {
    c.name = text; c.total = c.item.price_ngn * c.qty + c.fee; step = 'confirm'; advance = true;
    reply = `Please confirm:\n${c.qty} x ${c.item.name}\nDelivery (${c.zone}): ${naira(c.fee)}\nTotal: ${naira(c.total)}\nReply YES to confirm or CANCEL.`;
  } else reply = 'Please send your name (letters only).';
}
else if (step === 'confirm') {
  if (/^(yes|y|confirm|ok|okay)$/i.test(text.trim())) done = true;
  else reply = 'Reply YES to confirm, or CANCEL to stop.';
}
attempts = (advance || done) ? 0 : attempts + 1;

const q = v => v === null || v === undefined
  ? 'NULL'
  : "'" + String(v).replace(/\0/g, '').replace(/'/g, "''") + "'";

const save_sql = `INSERT INTO conversation_state (phone_hash, intent, step, collected_json, attempts, expires_at)
VALUES (${q(st.phone_hash)}, 'place_order', ${q(step)}, ${q(JSON.stringify(c))}, ${Number(attempts)},
        now() + interval '${Number(cfg.state_ttl_min)} minutes')
ON CONFLICT (phone_hash) DO UPDATE SET
  step = EXCLUDED.step, collected_json = EXCLUDED.collected_json,
  attempts = EXCLUDED.attempts, expires_at = EXCLUDED.expires_at;`;

return [{ json: { phone_hash: st.phone_hash, step, attempts, advance, done,
  escalate: attempts >= cfg.max_attempts, reply_text: reply,
  collected: c, collected_json: JSON.stringify(c), save_sql } }];

const crypto = require('crypto');
const q = v => v === null || v === undefined
  ? 'NULL'
  : "'" + String(v).replace(/\0/g, '').replace(/'/g, "''") + "'";

const ps = $('PlaceOrder Step').first().json;
const c  = ps.collected;
const order_id = 'ZH-' + (10000 + crypto.randomInt(90000));
const items = JSON.stringify([{ sku: c.item.sku, name: c.item.name, qty: c.qty, unit_price: c.item.price_ngn }]);

const sql = `INSERT INTO orders (order_id, phone_hash, status, items_json, total_ngn, delivery_zone, address, customer_name)
VALUES (${q(order_id)}, ${q(ps.phone_hash)}, 'awaiting_payment', ${q(items)}, ${Number(c.total)}, ${q(c.zone)}, ${q(c.address)}, ${q(c.name)});`;

return [{ json: { order_id, sql } }];

