INSERT INTO contacts (phone_hash, wa_phone)
VALUES ('{{ $('Hash and Mask Phone Number').item.json.phone_hash }}', '{{ $('Hash and Mask Phone Number').item.json.wa_phone }}')
ON CONFLICT (phone_hash) DO UPDATE SET last_seen = now();

UPDATE messages
SET intent = '{{ $('Classifier').item.json.intent }}',
    confidence = {{ Number($('Classifier').item.json.confidence) }}
WHERE wa_message_id = '{{ String($('Classifier').item.json.wa_message_id).replace(/'/g, "''") }}';
